  "codebook": {
    "definition": "Credit-claiming is defined as any public statement in which a senator claims personal or joint responsibility for securing a specific, positive outcome from the government (e.g., federal funding, local projects, passed legislation, policy changes, or expedited regulatory approvals) that benefits their state constituents or the nation as a whole.",
    "clarification": "To qualify as credit-claiming, the text must highlight the senator's active role (e.g., authoring a bill that passed, adding an amendment, lobbying an agency, writing letters of support that yielded results, or serving on an appropriations committee directing funds) in bringing about a completed or significantly advanced material benefit. Standard press releases announcing federal grants awarded to the senator's state are included, as are references to past successful policy achievements they enacted.",
    "positive_examples": [
      {
        "document_id": "1862",
        "explanation": "Senators Baucus and Tester explicitly state that they 'have delivered on their promise to secure federal funding' ($12.5 million for Butte) in the Defense Appropriations Bill."
      },
      {
        "document_id": "2697",
        "explanation": "Senator Inouye details his personal action in finding and securing a $225,000 federal grant source after the administration initially denied funding."
      },
      {
        "document_id": "1257",
        "explanation": "Senator DeWine announces a federal grant and explicitly claims credit for writing and passing the underlying FIRE Act that established the grant program."
      }
    ],
    "negative_clarification": "Do not classify a text as credit-claiming if the senator is merely introducing or cosponsoring a new bill that has not yet passed, explaining a legislative vote, expressing a general policy stance, criticizing an opponent or the administration, or writing letters/making appeals without having secured a concrete outcome. Purely symbolic resolutions, tributes, and standard committee oversight discussions are also excluded.",
    "negative_examples": [
      {
        "document_id": "656",
        "explanation": "Senator Kerry criticizes the Bush Administration's incompetence regarding port security. This is partisan position-taking and does not claim any secured positive policy outcome."
      },
      {
